package za.ac.cput.adp_assignment02.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Lob;
import jakarta.persistence.Table;
import jakarta.validation.constraints.NotBlank;

import java.time.LocalDate;
import java.util.Objects;

/* * Customer.java *
Customer model class
* Author: David Daniel Sepkitt (240046935)
* Date: 10 August 2026
* Updated: customer ID is now auto-generated by the service (e.g. CUS-0001),
*          only first/last name are required, and an optional image is stored.
*/

@Entity
@Table(name = "customer")
public class Customer {
    @Id
    @Column(name = "custID")
    private String custID;
    @NotBlank(message = "Customer name is required.")
    @Column(nullable = false)
    private String firstName;
    @Column(nullable = false)
    private String lastName;
    private String email;
    private String phoneNumber;
    private String address;
    private String company;

    /* Image stored as a data URL (e.g. "data:image/jpeg;base64,...") */
    @Lob
    @Column(columnDefinition = "LONGTEXT")
    private String imageUrl;

    private LocalDate createdDate;
    private LocalDate lastPurchaseDate;

    public Customer() {
    }

    private Customer(Builder builder) {
        this.custID = builder.custID;
        this.firstName = builder.firstName;
        this.lastName = builder.lastName;
        this.email = builder.email;
        this.phoneNumber = builder.phoneNumber;
        this.address = builder.address;
        this.company = builder.company;
        this.imageUrl = builder.imageUrl;
        this.createdDate = builder.createdDate;
        this.lastPurchaseDate = builder.lastPurchaseDate;
    }

    public String getCustID() {
        return custID;
    }

    public void setCustID(String custID) {
        this.custID = custID;
    }

    public String getFirstName() {
        return firstName;
    }

    public void setFirstName(String firstName) {
        this.firstName = firstName;
    }

    public String getLastName() {
        return lastName;
    }

    public void setLastName(String lastName) {
        this.lastName = lastName;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getPhoneNumber() {
        return phoneNumber;
    }

    public void setPhoneNumber(String phoneNumber) {
        this.phoneNumber = phoneNumber;
    }

    public String getAddress() {
        return address;
    }

    public void setAddress(String address) {
        this.address = address;
    }

    public String getCompany() {
        return company;
    }

    public void setCompany(String company) {
        this.company = company;
    }

    public String getImageUrl() {
        return imageUrl;
    }

    public void setImageUrl(String imageUrl) {
        this.imageUrl = imageUrl;
    }

    public LocalDate getCreatedDate() {
        return createdDate;
    }

    public void setCreatedDate(LocalDate createdDate) {
        this.createdDate = createdDate;
    }

    public LocalDate getLastPurchaseDate() {
        return lastPurchaseDate;
    }

    public void setLastPurchaseDate(LocalDate lastPurchaseDate) {
        this.lastPurchaseDate = lastPurchaseDate;
    }

    public String getFullName() {
        return ((firstName == null ? "" : firstName) + " " + (lastName == null ? "" : lastName)).trim();
    }

    @Override
    public String toString() {
        return "Customer{" + "Customer ID='" + custID + '\'' + ", First name='" + firstName + '\'' + ", Last name='" + lastName + '\'' + ", Email address='" + email + '\'' + ", Phone number='" + phoneNumber + '\'' + ", Address='" + address + '\'' + '}';
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof Customer)) {
            return false;
        }
        Customer customer = (Customer) o;
        return Objects.equals(custID, customer.custID);
    }

    @Override
    public int hashCode() {
        return Objects.hash(custID);
    }

    public static class Builder {
        private String custID;
        private String firstName;
        private String lastName;
        private String email;
        private String phoneNumber;
        private String address;
        private String company;
        private String imageUrl;
        private LocalDate createdDate;
        private LocalDate lastPurchaseDate;

        public Builder setCustID(String custID) {
            this.custID = custID;
            return this;
        }

        public Builder setFirstName(String firstName) {
            this.firstName = firstName;
            return this;
        }

        public Builder setLastName(String lastName) {
            this.lastName = lastName;
            return this;
        }

        public Builder setEmail(String email) {
            this.email = email;
            return this;
        }

        public Builder setPhoneNumber(String phoneNumber) {
            this.phoneNumber = phoneNumber;
            return this;
        }

        public Builder setAddress(String address) {
            this.address = address;
            return this;
        }

        public Builder setCompany(String company) {
            this.company = company;
            return this;
        }

        public Builder setImageUrl(String imageUrl) {
            this.imageUrl = imageUrl;
            return this;
        }

        public Builder setCreatedDate(LocalDate createdDate) {
            this.createdDate = createdDate;
            return this;
        }

        public Builder setLastPurchaseDate(LocalDate lastPurchaseDate) {
            this.lastPurchaseDate = lastPurchaseDate;
            return this;
        }

        public Customer build() {
            return new Customer(this);
        }
    }
}
